import os
import re
import json
import csv

# Available ingredients
available = {
    '鸡蛋': '2个',
    '土豆': '100g',
    '茄子': '200g',
    '蒜苗': '100g',
    '冬瓜': '100g',
    '瘦猪肉片': '150g',
    '五花肉': '100g',
    '牛奶': '30ml',
    '干辣椒': '50g',
}

avail_names = list(available.keys())

# Map of ingredient variations to canonical names
ingredient_variants = {
    '鸡蛋': ['鸡蛋', '蛋'],
    '土豆': ['土豆', '马铃薯'],
    '茄子': ['茄子'],
    '蒜苗': ['蒜苗', '蒜苔'],
    '冬瓜': ['冬瓜'],
    '瘦猪肉片': ['瘦猪肉片', '瘦猪肉', '猪肉片'],
    '五花肉': ['五花肉'],
    '牛奶': ['牛奶'],
    '干辣椒': ['干辣椒', '干红辣椒'],
}

reverse_map = {}
for canonical, variants in ingredient_variants.items():
    for v in variants:
        reverse_map[v] = canonical

def extract_dish_name(filepath):
    parts = filepath.split('/')
    for part in parts:
        if part.endswith('.md'):
            return part[:-3]
    return 'unknown'

def parse_ingredients(content):
    in_jisuan = False
    ingredients = []
    for line in content.split('\n'):
        stripped = line.strip()
        if stripped.startswith('## 计算'):
            in_jisuan = True
            continue
        if in_jisuan and stripped.startswith('##'):
            break
        if in_jisuan and (stripped.startswith('- ') or stripped.startswith('* ')):
            item = stripped.lstrip('- * ')
            # Match patterns like: 冬瓜 300 g, 五花肉 0.5 斤, 鸡蛋 2个
            match = re.match(r'(.+?)\s+(\d+\s*[,，\.]\s*\d*|\d+)\s*(\S+)?', item)
            if match:
                name = match.group(1).strip()
                amount_raw = match.group(2).strip()
                unit = match.group(3) if match.group(3) else ''
                ingredients.append((name, f"{amount_raw} {unit}".strip()))
            else:
                ing = item.strip()
                if ing:
                    ingredients.append((ing, ''))
    return ingredients

def normalize_name(name):
    name = name.strip()
    if name in reverse_map:
        return reverse_map[name], name
    for av in avail_names:
        if av in name or name in av:
            return av, name
    return None, name

recipe_dir = '/app/HowToCook/dishes'
recipes = []

for root, dirs, files in os.walk(recipe_dir):
    for f in files:
        if f.endswith('.md') and '示例菜' not in root and 'template' not in root:
            filepath = os.path.join(root, f)
            try:
                with open(filepath, 'r', encoding='utf-8') as fh:
                    content = fh.read()
            except:
                continue
            dish_name = extract_dish_name(filepath)
            ingredients = parse_ingredients(content)
            matched = []
            for ing_name, ing_amount in ingredients:
                can_name, _ = normalize_name(ing_name)
                if can_name and can_name in available:
                    matched.append((can_name, ing_name, ing_amount))
            if matched:
                recipes.append({
                    'name': dish_name,
                    'path': filepath,
                    'matched': matched,
                    'match_count': len(matched),
                    'match_names': [m[0] for m in matched],
                    'all_ingredients': [(n, a) for n, a in ingredients],
                })

recipes.sort(key=lambda x: x['match_count'], reverse=True)

print("Top matching recipes:")
for i, r in enumerate(recipes[:25]):
    print(f"\n{i+1}. {r['name']} ({r['match_count']} matches)")
    print(f"   Matched: {r['match_names']}")
    print(f"   Ingredients: {[(n, a) for n, a in r['all_ingredients']]}")

print(f"\nTotal recipes parsed: {len(recipes)}")
