available = {
    '鸡蛋': '2个',
    '土豆': '100g',
    '茄子': '200g',
    '蒜苗': '100g',
    '冬瓜': '100g',
    '瘦猪肉片': '150g',
    '五花肉': '100g',
    '牛奶': '30ml',
    '干辣椒': '50g',
}

# 3 selected dishes with exact ingredient amounts from the MCP server (HowToCook)
# Based on the recipe files from https://github.com/Anduin2017/HowToCook

selected_dishes = [
    {
        "name": "炒滑蛋",
        "ingredients": [
            {"name": "鸡蛋", "quantity": "4颗"},
            {"name": "牛奶", "quantity": "30ml"},
            {"name": "食用油", "quantity": "10ml"}
        ]
    },
    {
        "name": "地三鲜",
        "ingredients": [
            {"name": "茄子", "quantity": "200g"},
            {"name": "土豆", "quantity": "150g"},
            {"name": "尖椒", "quantity": "3-4个"},
            {"name": "淀粉", "quantity": "8g"}
        ]
    },
    {
        "name": "燕麦鸡蛋饼",
        "ingredients": [
            {"name": "鸡蛋", "quantity": "2个"},
            {"name": "纯干燕麦片", "quantity": "50g"},
            {"name": "牛奶", "quantity": "250ml"},
            {"name": "蔬菜碎叶", "quantity": "一把"}
        ]
    }
]

# Calculate shopping list: ingredients needed minus what we have
shopping_list = []

dish_names = []
cuisine_data = {
    "recommended_dishes": []
}

for dish in selected_dishes:
    dish_entry = {
        "name": dish["name"],
        "ingredients": []
    }
    for ing in dish["ingredients"]:
        ing_name = ing["name"]
        ing_qty = ing["quantity"]

        dish_entry["ingredients"].append({
            "name": ing_name,
            "quantity": ing_qty
        })

        # Check if we have this ingredient
        if ing_name in available:
            avail_qty = available[ing_name]
            # We have it, skip shopping list
            pass
        else:
            # Missing or insufficient - add to shopping list
            shopping_list.append({
                "Name": ing_name,
                "Quantity": ing_qty
            })

    cuisine_data["recommended_dishes"].append(dish_entry)
    dish_names.append(dish["name"])

# Write cuisine.json
with open('/app/cuisine.json', 'w', encoding='utf-8') as f:
    json.dump(cuisine_data, f, ensure_ascii=False, indent=4)

print("cuisine.json written.")
print(json.dumps(cuisine_data, ensure_ascii=False, indent=4))

# Write shopping.csv
with open('/app/shopping.csv', 'w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Name', 'Quantity'])
    writer.writeheader()
    for item in shopping_list:
        writer.writerow(item)

print("\nshopping.csv written.")
print("Shopping list items:")
for item in shopping_list:
    print(f"  {item['Name']}: {item['Quantity']}")

# Print analysis
print("\n=== Analysis ===")
for dish in selected_dishes:
    matched = []
    total = len(dish['ingredients'])
    for ing in dish['ingredients']:
        if ing['name'] in available:
            matched.append(ing['name'])
    ratio = len(matched) / total if total > 0 else 0
    print(f"{dish['name']}: {len(matched)}/{total} ingredients from stock ({ratio:.0%}) - matched: {matched}")
